    // ─── TSTypeReference helpers ──────────────────────────────────────────────

    /// Extract the name part of a TSTypeReference (for checking FC, forwardRef, etc.)
    pub(super) fn extract_type_ref_name<'a>(&self, tr: &TSTypeReference<'a>) -> String {
        self.ts_type_name_str(&tr.type_name)
                value_type.structural_hash(hasher);
                optional.hash(hasher);
            }
            CollectedType::Raw(s) => s.hash(hasher),
        }
    }

    /// True if this type requires the TypeScript type checker to resolve.
    pub fn needs_type_checker(&self) -> bool {
        matches!(self, CollectedType::Conditional { .. } | CollectedType::Mapped { .. })
    }

    /// Extract literal string keys from a type shaped like `'a' | 'b'` or a bare
    /// `'a'`. Used for `Pick`/`Omit`'s key argument. Returns an empty vec for
    /// anything else — notably `keyof T`, which can't be read as a string list
    /// (see `CollectedTypeAlias::Omit::keys`, which resolves the
    /// operand as a props chain instead).
    pub fn as_string_union_keys(&self) -> Vec<std::string::String> {
        match self {
            CollectedType::StringLiteral(s) => vec![s.to_string()],
            CollectedType::Union(members) => members.iter().flat_map(CollectedType::as_string_union_keys).collect(),
            _ => vec![],
        }
    }

    /// Produce a raw string representation for diagnostics and fallback display.
    pub fn to_raw_string(&self) -> std::string::String {
        match self {
            CollectedType::String => "string".into(),
            CollectedType::Number => "number".into(),
            CollectedType::Boolean => "boolean".into(),
}

#[test]
fn test_type_alias_omit() {
    let source = r#"
        interface FullProps { a: string; b: number; c: boolean; }
        type PartialProps = Omit<FullProps, 'b' | 'c'>;
    "#;
    let path = Utf8Path::new("/test/types.ts");
    let data = parse_file(path, source);

    let alias = data.type_aliases.get("/test/types.ts:PartialProps");
    assert!(alias.is_some(), "PartialProps alias not collected");
    match alias.unwrap() {
        CollectedTypeAlias::Omit { base, keys, .. } => {
            assert_eq!(base.to_raw_string(), "FullProps");
            assert_eq!(keys.as_string_union_keys(), vec!["b".to_owned(), "c".to_owned()]);
        }
        other => panic!("Expected Omit, got {:?}", other),
    }
}
}

#[test]
fn omit_with_a_literal_base_is_collected_structurally_for_the_resolver_to_report() {
    // The base is kept as written; whether it can supply props is the resolver's call, which reports a literal base
    // when it is used as props ("cannot be used as a component's props base").
    let source = r#"
        type BadOmit2 = Omit<"not a type reference", 'a' | 'b'>;
    "#;
    let path = Utf8Path::new("/test/malformed_omit2.ts");
    let data = parse_file(path, source);

    match data.type_aliases.get(&format!("{}:BadOmit2", path)) {
        Some(CollectedTypeAlias::Omit { base, keys, .. }) => {
            assert!(matches!(base, CollectedType::StringLiteral(s) if s == "not a type reference"));
            assert_eq!(keys.as_string_union_keys(), vec!["a".to_owned(), "b".to_owned()]);
        }
        other => panic!("expected an Omit alias, got {other:?}"),
    }
}

